// Canonical Wireline "W" glyph. Drop-in replacement for the lucide
// `<Waves />` icon that used to live inside every brand chrome container.
// The cyan square + shadow stay on the parent <div>; this component
// renders only the white W stroke so it inherits sizing the same way
// the lucide icon did.
//
// For OS-level surfaces (favicon, apple touch icon, og-image) the source
// is `public/favicon.svg` + `scripts/apple-touch-icon.svg` — same path,
// regenerated by `npm run assets`.

interface Props {
  /** Tailwind sizing (`w-4 h-4` etc.) — same convention as lucide icons. */
  className?: string;
  /** Stroke color. Default white so it reads on the cyan brand chip. */
  stroke?: string;
  /** Stroke width in the 1024 viewbox space. Default 110 mirrors the
   *  master source. Tune up (140) when the glyph sits inside a small
   *  container and needs more visual weight. */
  strokeWidth?: number;
}

export default function WirelineMark({
  className = "w-4 h-4",
  stroke = "currentColor",
  strokeWidth = 110,
}: Props) {
  return (
    <svg
      viewBox="0 0 1024 1024"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      aria-hidden="true"
    >
      <path
        d="M 220 300 L 392 712 L 512 470 L 632 712 L 804 300"
        fill="none"
        stroke={stroke}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}
